<?php
namespace App\Console\Commands;
use App\Support\{ModuleCatalog,PermissionCatalog};use Illuminate\Console\Command;use Illuminate\Support\Facades\Schema;
/** Provides p10 chat doctor behavior within the WorkIntel application. */ class ChatCollaborationDoctor extends Command{
 protected $signature='workintel:p10-doctor';protected $description='Validate P10 Chat, collaboration and drag/drop architecture.';
 /** Executes the command, job, or request handler. */ public function handle():int{$errors=[];foreach(['chat_conversations','chat_conversation_members','chat_messages','chat_message_attachments','chat_message_reactions','chat_message_pins','chat_presence']as$t)if(!Schema::hasTable($t))$errors[]="Missing {$t}.";foreach(['chat.view','chat.create','chat.manage','chat.moderate']as$slug)if(!collect(PermissionCatalog::ITEMS)->contains(fn($x)=>$x[1]===$slug))$errors[]="Missing permission {$slug}.";if(!isset(ModuleCatalog::DEFINITIONS['chat']))$errors[]='Chat module missing.';$pkg=base_path('package.json');$json=is_file($pkg)?json_decode(file_get_contents($pkg),true):[];if(empty($json['dependencies']['gridstack']))$errors[]='GridStack dependency missing.';if(empty($json['dependencies']['@dnd-kit/core']))$errors[]='dnd-kit dependency missing.';if(!is_file(base_path('resources/js/components/DashboardGrid.tsx')))$errors[]='DashboardGrid missing.';if(!is_file(base_path('resources/js/pages/Chat.tsx')))$errors[]='Chat page missing.';if($errors){foreach($errors as$e)$this->error($e);return self::FAILURE;}$this->info('P10 Chat & Collaboration + drag/drop architecture: PASS');return self::SUCCESS;}
}
